files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #8a8fa8;
  --border: #2a2a4a;
  --radius: 8px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 3px solid var(--border);
  border-radius: var(--radius);
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 20px;
  text-align: center;
  letter-spacing: 0.05em;
  color: var(--accent);
}

.task-form {
  display: flex;
  gap: 8px;
  margin-bottom: 20px;
}

input[type="text"] {
  flex: 1;
  min-width: 0;
  padding: 10px 12px;
  font-size: 1rem;
  font-family: inherit;
  color: var(--text);
  background: var(--bg);
  border: 2px solid var(--border);
  border-radius: var(--radius);
  outline: none;
  transition: border-color 0.15s;
}

input[type="text"]:focus-visible {
  border-color: var(--accent);
}

button {
  font-family: inherit;
  font-size: 1rem;
  padding: 10px 16px;
  border: 2px solid var(--border);
  border-radius: var(--radius);
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  transition: background 0.15s, transform 0.05s;
  white-space: nowrap;
}

button:hover {
  background: #f05a72;
}

button:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

button:active {
  transform: translateY(1px);
}

.task-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.task-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  background: var(--bg);
  border: 2px solid var(--border);
  border-radius: var(--radius);
  transition: border-color 0.15s;
}

.task-item.running {
  border-color: var(--accent);
}

.task-label {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 1rem;
}

.task-time {
  font-variant-numeric: tabular-nums;
  font-size: 1rem;
  color: var(--muted);
  min-width: 52px;
  text-align: right;
}

.task-item.running .task-time {
  color: var(--accent);
  font-weight: 700;
}

.task-item button {
  padding: 6px 12px;
  font-size: 0.875rem;
}

.task-item .stop-btn {
  background: var(--muted);
  color: var(--bg);
}

.task-item .stop-btn:hover {
  background: #a0a5bd;
}

.task-item .remove-btn {
  background: transparent;
  color: var(--muted);
  border-color: var(--border);
}

.task-item .remove-btn:hover {
  background: var(--accent);
  color: #fff;
  border-color: var(--accent);
}

.empty-msg {
  text-align: center;
  color: var(--muted);
  font-size: 0.9375rem;
  padding: 12px 0;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

@media (max-width: 400px) {
  .task-form {
    flex-direction: column;
  }
  .task-item {
    flex-wrap: wrap;
  }
  .task-label {
    flex-basis: 100%;
  }
}

(function () {
  'use strict';

  var tasks = [];
  var nextId = 1;
  var activeId = null;
  var tickInterval = null;

  var form = document.getElementById('task-form');
  var input = document.getElementById('task-input');
  var list = document.getElementById('task-list');
  var emptyMsg = document.getElementById('empty-msg');

  function formatTime(totalSeconds) {
    var m = Math.floor(totalSeconds / 60);
    var s = totalSeconds % 60;
    return (m < 10 ? '0' : '') + m + ':' + (s < 10 ? '0' : '') + s;
  }

  function stopActive() {
    if (activeId === null) return;
    var t = findTask(activeId);
    if (t) t.running = false;
    activeId = null;
    if (tickInterval) {
      clearInterval(tickInterval);
      tickInterval = null;
    }
  }

  function findTask(id) {
    for (var i = 0; i < tasks.length; i++) {
      if (tasks[i].id === id) return tasks[i];
    }
    return null;
  }

  function render() {
    list.innerHTML = '';
    emptyMsg.style.display = tasks.length ? 'none' : 'block';

    tasks.forEach(function (task) {
      var li = document.createElement('li');
      li.className = 'task-item' + (task.running ? ' running' : '');
      li.dataset.id = task.id;

      var label = document.createElement('span');
      label.className = 'task-label';
      label.textContent = task.label;

      var time = document.createElement('span');
      time.className = 'task-time';
      time.textContent = formatTime(task.elapsed);

      var toggleBtn = document.createElement('button');
      toggleBtn.type = 'button';
      toggleBtn.className = task.running ? 'stop-btn' : 'start-btn';
      toggleBtn.textContent = task.running ? 'Stop' : 'Start';
      toggleBtn.setAttribute('aria-label', (task.running ? 'Stop' : 'Start') + ' timer for ' + task.label);
      toggleBtn.addEventListener('click', function () {
        toggleTask(task.id);
      });

      var removeBtn = document.createElement('button');
      removeBtn.type = 'button';
      removeBtn.className = 'remove-btn';
      removeBtn.textContent = 'Remove';
      removeBtn.setAttribute('aria-label', 'Remove task ' + task.label);
      removeBtn.addEventListener('click', function () {
        removeTask(task.id);
      });

      li.appendChild(label);
      li.appendChild(time);
      li.appendChild(toggleBtn);
      li.appendChild(removeBtn);
      list.appendChild(li);
    });
  }

  function toggleTask(id) {
    var task = findTask(id);
    if (!task) return;

    if (task.running) {
      stopActive();
      render();
      return;
    }

    stopActive();
    task.running = true;
    activeId = id;

    if (tickInterval) clearInterval(tickInterval);
    tickInterval = setInterval(function () {
      var active = findTask(activeId);
      if (!active) return;
      active.elapsed += 1;
      var li = list.querySelector('.task-item[data-id="' + activeId + '"]');
      if (li) {
        var timeEl = li.querySelector('.task-time');
        if (timeEl) timeEl.textContent = formatTime(active.elapsed);
      }
    }, 1000);

    render();
  }

  function removeTask(id) {
    if (activeId === id) stopActive();
    tasks = tasks.filter(function (t) { return t.id !== id; });
    render();
  }

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var text = input.value.trim();
    if (!text) return;
    tasks.push({
      id: nextId++,
      label: text,
      elapsed: 0,
      running: false
    });
    input.value = '';
    input.focus();
    render();
  });

  render();
})();
